new_setup='''export const ExpressHttpStreamableMcpServer = (options: ServerOptions, setupCb: (server: McpServer) => void) => {
  // An McpServer can only be connected to one transport at a time, so each
  // session gets its own instance. Sharing one instance across sessions makes
  // earlier sessions hang as soon as a second client connects.
  const createServer = () => {
    const server = new McpServer({
      name: options.name,
      version: "1.0.0",
    }, {
      capabilities: {
        logging: {},
        tools: {
          listChanged: false
        }
      }
    });
    setupCb(server);
    return server;
  };

  const app = express();
  app.use(express.json());

  // Health check endpoint for the hosting platform
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  // Per the MCP spec, an unknown/expired session ID gets a 404 so clients know
  // to start a new session (e.g. after a redeploy or restart wipes memory).
  const sessionNotFound = (res: express.Response) => {
    res.status(404).json({
      jsonrpc: '2.0',
      error: { code: -32001, message: 'Session not found' },
      id: null,
    });
  };
'''
